async function loadProfiles(){try{const r=await fetch(new URL('../photo-profiles.json',DATA_URL),{cache:'no-store'});if(!r.ok){profileData=null;profileStatus=r.status===404?'未作成（photo-profiles.json）':'取得待ち HTTP '+r.status;return;}profileData=await r.json();profileStatus='取得済み';if(dataset){for(const b of dataset.buildings){const p=profileFor(b.buildingId);if(!p)continue;b.profile=p;b.profileEvidenceStatus=p.evidenceStatus;b.evidenceStatus=p.evidenceStatus==='insufficient'?'pending':'observed';if(p.artwork)b.artworkPath='../'+p.artwork;else if(p.evidenceStatus!=='approved-central')b.artworkPath=null;}dataset.summary.profileCounts=Object.fromEntries(['street-photo','native-photo-pattern','insufficient','approved-central'].map(s=>[s,dataset.buildings.filter(b=>b.profileEvidenceStatus===s).length]));renderCounts();}}catch{profileData=null;profileStatus='未作成、または読込待ち';}}
