async function start(){try{const r=await fetch(DATA_URL,{cache:'no-store'});if(!r.ok)throw Error('ソース索引 HTTP '+r.status);dataset=await r.json();if(dataset.buildings.length!==83)throw Error('固定スコープが83棟ではありません');renderCounts();document.querySelector('#snapshot').textContent='索引作成: '+dataset.generatedAt+' / 出典マニフェスト: '+dataset.manifests.map(m=>m.file.split('/').pop()+' '+m.status).join(' · ');const requested=new URLSearchParams(location.search).get('building')??decodeURIComponent(location.hash.slice(1));selectedId=dataset.buildings.some(b=>b.buildingId===requested)?requested:dataset.buildings[0].buildingId;if(new URLSearchParams(location.search).has('building')&&dataset.buildings.some(b=>b.buildingId===requested))document.querySelector('#query').value=requested;await loadProfiles();renderList();}catch(e){const n=document.querySelector('#loadError');n.hidden=false;n.className='error';n.textContent='読み込めませんでした: '+e.message+'。HTTPサーバーからこのページを開いてください。';document.querySelector('#detail').textContent='レビュー索引の読込待ちです。';}}
document.querySelector('#query').addEventListener('input',()=>dataset&&renderList());document.querySelector('#filter').addEventListener('change',()=>dataset&&renderList());document.querySelector('#clear').addEventListener('click',()=>{document.querySelector('#query').value='';document.querySelector('#filter').value='all';if(dataset)renderList();});document.querySelector('#refresh').addEventListener('click',async()=>{nonce=String(Date.now());await loadProfiles();if(dataset)renderList();});window.addEventListener('hashchange',()=>{const id=decodeURIComponent(location.hash.slice(1));if(dataset?.buildings.some(b=>b.buildingId===id)){selectedId=id;document.querySelector('#query').value='';document.querySelector('#filter').value='all';renderList();}});start();
